\title[Large primes are split primes]{Large Primes Are Split Primes:\\
The Large-Prime Variant of the Quadratic Sieve Cannot Decouple\\
the Factor Base from the Split Set}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
The quadratic sieve factors $N$ by collecting smooth values of $f(c)=c^2-N$ and combining them, by linear algebra over $\F_2$, into a congruence of squares. The columns of the linear system are primes $p$ at which $N$ is a square modulo $p$, which we call the \emph{split set}. One natural question about the large-prime (partial-relation) variant is whether it can decouple the number of columns from the split set, so that column count becomes a free design parameter. We show that it cannot, and the main step takes one line: if a prime $r$ divides $c^2-N$, then $N\equiv c^2\pmod r$, so $\leg{N}{r}=+1$ whenever $r\nmid N$. We build a small theory around this fact: exact hit counts $1+\leg{N}{r}$; the analogue for every quadratic polynomial of discriminant $D$; containment of the columns of any large-prime relation matrix in the split set up to $L$, with strict enlargement by any genuine large prime; and periodicity of splitness modulo $4N$. In the other direction, after partial relations are paired the large primes cancel, and $Q(B)+1$ combined relations already contain a square product. The final matrix therefore has $Q(B)$ columns, whatever the large-prime bound. The large-prime variant neither decouples nor enlarges the final column count: it is purely a row-yield accelerator. We illustrate every statement numerically, including a complete toy factorisation, and formulate four conjectures.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The quadratic sieve}
Let $N$ be an odd composite integer that is not a prime power. If $X^2\equiv Y^2\pmod N$ with $X\not\equiv\pm Y$, then $\gcd(X-Y,N)$ is a proper divisor of $N$. The quadratic sieve produces such pairs as follows. For integers $c$ near $\sqrt N$ the value
\[
  f(c)=c^2-N
\]
is small, of order $2\sqrt N\,|c-\sqrt N|$, and so is relatively likely to be $B$-\emph{smooth}. Each smooth value gives a \emph{relation} $c^2\equiv f(c)\pmod N$. Reducing exponent vectors modulo $2$ gives rows of a matrix over $\F_2$. Once there are more rows than columns, a nonempty set of rows sums to zero, and the product of the corresponding relations is a congruence of squares.

\subsection{The split set}
A prime $r$ divides some value $f(c)$ if and only if $N$ is a square modulo $r$. Primes with $\leg{N}{r}=-1$ (\emph{inert} primes) never divide a value. The factor base is therefore the set of primes up to $B$ at which $N$ is a square. Its size $Q(B)$ is determined by $N$ and $B$, with $Q(B)\approx\tfrac12\pi(B)$ when $N$ is not a perfect square.

\subsection{The question}
Three mechanisms suggest themselves for escaping the dependence of the column count on the split set: (a) the large-prime, or partial-relation, variant; (b) multiple polynomials; (c) an adaptive bound $B$. This paper settles (a) analytically. In the large-prime variant, a value $f(c)=s\cdot r$ with $s$ $B$-smooth and $r$ a single prime in $(B,L]$ is kept as a \emph{partial relation}, and $r$ becomes a new column. The hope is that such ``large'' columns are not tied to the split condition.

\subsection{Summary of results}
The hope fails, because \emph{every large prime is a split prime} (Theorem~\ref{thm:split}). At the partial stage, every column is a split prime up to $L$ (Theorems~\ref{thm:support} and~\ref{thm:columns}). A genuine large prime strictly enlarges the split set (Theorem~\ref{thm:strict}), and the added columns are exactly the split primes in $(B,L]$ (Proposition~\ref{prop:extra}). Splitness is a congruence condition modulo $4N$ (Theorem~\ref{thm:periodic}). At the final stage, after pairing (Theorem~\ref{thm:pair}), the large primes cancel and the matrix has $Q(B)$ columns (Theorem~\ref{thm:combined}). Neither stage decouples the column count from the split set (Corollary~\ref{cor:main}).

\section{Definitions and notation}

Throughout, $N$ is an integer (positive when stated) and $f(c)=c^2-N$. For an odd prime $r$, $\leg{a}{r}$ denotes the Legendre symbol. For odd positive $n$, $\leg{a}{n}$ denotes the Jacobi symbol.

\begin{definition}[Split, inert, ramified]
An odd prime $r$ is \emph{split} for $N$ if $\leg{N}{r}=+1$, \emph{inert} if $\leg{N}{r}=-1$, and \emph{ramified} if $r\mid N$.
\end{definition}

\begin{definition}[Admissible primes; the split set]
For $L\ge1$ let
\[
  \A(N,L)=\{\,p\le L\ \text{prime} : N \text{ is a square in } \Z/p\Z\,\},\qquad Q(L)=|\A(N,L)|.
\]
This set contains $2$, the split primes up to $L$, and the ramified primes up to $L$. Clearly $\A(N,B)\subseteq\A(N,L)$ for $B\le L$.
\end{definition}

\begin{definition}[Relations]
A \emph{full relation} is a pair $(c,f(c))$ with $f(c)\ne0$ and $B$-smooth. A \emph{partial relation} has $f(c)=s\cdot r$ with $s$ $B$-smooth and $r$ prime, $B<r\le L$. An \emph{LP-$k$ relation} allows up to $k$ prime factors in $(B,L]$.
\end{definition}

\begin{definition}[Quadratic polynomials]
The polynomial $g(x)=ax^2+bx+c$ has discriminant $D=b^2-4ac$. The sieve polynomial $f$ has discriminant $4N$.
\end{definition}

\section{Large primes are split}

\begin{lemma}[Divisibility criterion]\label{lem:crit}
For a prime $r$, $r\mid f(c)$ if and only if $c^2=N$ in $\Z/r\Z$. Consequently, $r$ divides some value of $f$ if and only if $N$ is a square modulo $r$.
\end{lemma}
\begin{proof}
$r\mid c^2-N$ means exactly $c^2\equiv N\pmod r$. Conversely, lift any square root of $N$ modulo $r$ to an integer.
\end{proof}

\begin{theorem}[Large primes are split]\label{thm:split}
Let $r$ be a prime with $r\nmid N$ and $r\mid c^2-N$ for some integer $c$. Then $\leg{N}{r}=+1$.
\end{theorem}
\begin{proof}
$N\equiv c^2\pmod r$, so $N$ is a square modulo $r$, and it is nonzero because $r\nmid N$.
\end{proof}

\begin{remark}
The size of $r$ never enters. ``Large'' primes satisfy exactly the same condition as factor-base primes.
\end{remark}

\begin{corollary}[No inert columns]\label{cor:inert}
If a prime $r$ divides some value of $f$, then $\leg{N}{r}\ne-1$; no coprimality assumption is needed. Hence $\leg{N}{r}\in\{0,1\}$, with $0$ exactly when $r\mid N$. Equivalently, an inert prime divides no value of $f$.
\end{corollary}

\begin{theorem}[Euler form]\label{thm:euler}
If $r$ is an odd prime, $r\nmid N$ and $r\mid c^2-N$, then $N^{(r-1)/2}\equiv1\pmod r$.
\end{theorem}
\begin{proof}
$N^{(r-1)/2}\equiv c^{r-1}\equiv1$ by Fermat's little theorem, since $r\nmid c$. Equivalently, apply Euler's criterion to Theorem~\ref{thm:split}.
\end{proof}

\begin{theorem}[Hit count]\label{thm:hit}
For an odd prime $r$ and any integer $N$,
\[
  \#\{\,c\in\Z/r\Z : r\mid c^2-N\,\}=1+\leg{N}{r}.
\]
\end{theorem}
\begin{proof}
This counts square roots of $N$ in $\F_r$. There is one root if $N\equiv0$, two roots $\pm t$ if $N\equiv t^2\ne0$ (distinct because $r$ is odd), and none if $N$ is a non-square.
\end{proof}

\begin{theorem}[Multiple polynomials]\label{thm:forms}
Let $g(x)=ax^2+bx+c$ have discriminant $D$. If a prime $r\nmid D$ divides $g(x)$ for some integer $x$, then $D$ is a nonzero square modulo $r$; for odd $r$, $\leg{D}{r}=+1$.
\end{theorem}
\begin{proof}
From $4a\,g(x)=(2ax+b)^2-D$ we get $D\equiv(2ax+b)^2\pmod r$.
\end{proof}

\section{The column set of large-prime relation matrices}

\begin{theorem}[Support theorem]\label{thm:support}
If $v=x^2-N\ne0$ and $L\ge|v|$, then every prime factor of $|v|$ lies in $\A(N,L)$.
\end{theorem}
\begin{proof}
A prime factor $p$ satisfies $p\le|v|\le L$, and $N$ is a square modulo $p$ by Lemma~\ref{lem:crit}.
\end{proof}

\begin{theorem}[Columns of LP relation matrices]\label{thm:columns}
Let $(x_i)_{i\in S}$ be a finite family such that every prime factor of each $|x_i^2-N|$ is at most $L$. The values may contain arbitrarily many primes above $B$. Let $\mathcal{C}$ be the set of all primes dividing some $x_i^2-N$. Then $\mathcal{C}\subseteq\A(N,L)$, hence $|\mathcal{C}|\le Q(L)$.
\end{theorem}
\begin{proof}
Each $p\in\mathcal{C}$ satisfies $p\le L$ and divides a value of $f$, so Lemma~\ref{lem:crit} applies.
\end{proof}

\begin{theorem}[A large prime strictly enlarges the split set]\label{thm:strict}
If a prime $r$ with $B<r\le L$ divides some value $x^2-N$, then $Q(B)<Q(L)$.
\end{theorem}
\begin{proof}
$\A(N,B)\subseteq\A(N,L)$. Also $r\in\A(N,L)$ by Lemma~\ref{lem:crit}, while $r\notin\A(N,B)$ because $r>B$.
\end{proof}

\begin{proposition}[The extra columns are exactly split primes]\label{prop:extra}
For $B\le L$,
\[
  Q(L)=Q(B)+\bigl|\A(N,L)\setminus\A(N,B)\bigr|,
\]
and $\A(N,L)\setminus\A(N,B)$ is the set of primes in $(B,L]$ at which $N$ is a square. Inert primes contribute nothing.
\end{proposition}

At the level of partial-relation bookkeeping, therefore, the large-prime variant does not decouple the column count from the split set: it draws its columns from a larger split set.

\section{Pairing and the final matrix}

\begin{theorem}[Pigeonhole pairing]\label{thm:pair}
Let $x_i^2-N=s_ir_i$ for $1\le i\le m$, with $s_i\ge1$ $B$-smooth and $r_i$ prime. Suppose all $r_i$ lie in a finite set $R$ with $|R|<m$. Then there are $i\ne j$ with $r_i=r_j$, and every prime with odd exponent in $(s_ir_i)(s_jr_j)$ lies in $\A(N,B)$.
\end{theorem}
\begin{proof}
The map $i\mapsto r_i$ is not injective. With $r=r_i=r_j$, the product equals $s_is_jr^2$, so its odd-exponent primes divide $s_is_j$. Each of them is at most $B$ and divides a value of $f$.
\end{proof}

Multiplying the two congruences yields the combined relation $(x_ix_j)^2\equiv s_is_jr^2\pmod N$.

\begin{theorem}[Combined relations need only $Q(B)+1$ rows]\label{thm:combined}
Let $x_{1,i}^2-N=s_{1,i}r_i$ and $x_{2,i}^2-N=s_{2,i}r_i$ for $1\le i\le n$, with $s_{1,i},s_{2,i}\ge1$ $B$-smooth and $r_i$ arbitrary positive integers. If $n>Q(B)$, there is a nonempty $T\subseteq\{1,\dots,n\}$ such that $\prod_{i\in T}(s_{1,i}r_i)(s_{2,i}r_i)$ is a perfect square.
\end{theorem}
\begin{proof}
All prime factors of $s_{1,i}s_{2,i}$ lie in $\A(N,B)$. The exponent vectors modulo $2$ are $n>Q(B)$ vectors in $\F_2^{\A(N,B)}$, so some nonempty subset $T$ sums to zero. Then
\[
  \prod_{i\in T}(s_{1,i}r_i)(s_{2,i}r_i)=\Bigl(\prod_{i\in T}s_{1,i}s_{2,i}\Bigr)\Bigl(\prod_{i\in T}r_i\Bigr)^2
\]
is a product of two squares.
\end{proof}

\begin{corollary}\label{cor:main}
The large-prime variant does not decouple the column count from the split set. At the partial stage its columns are split primes up to $L$. At the final stage the column count is $Q(B)$, plus a sign column if negative values occur, independently of $L$. Its only effect on the linear algebra is to supply more rows per unit of sieving: it is a pure row-yield accelerator.
\end{corollary}

\begin{remark}
``The large-prime variant adds split columns'' is true of the partial-relation matrix. ``The final matrix has $Q(B)$ columns'' is true after pairing. Both statements hold, and both rule out decoupling.
\end{remark}

\section{Reciprocity: the split set is a union of residue classes}

\begin{theorem}[Periodicity modulo $4N$]\label{thm:periodic}
Let $N>0$ and let $r,r'$ be odd primes with $r\equiv r'\pmod{4N}$. If $r\nmid N$ and $r\mid c^2-N$ for some $c$, then $r'\mid c'^2-N$ for some $c'$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:split}, $\leg{N}{r}=1$. Legendre and Jacobi symbols agree at primes. For fixed $N>0$, the Jacobi symbol $\leg{N}{n}$ on odd positive $n$ depends only on $n\bmod 4N$, by quadratic reciprocity and its supplementary laws. Hence $\leg{N}{r'}=1$. In particular $r'\nmid N$ and $N$ is a nonzero square modulo $r'$, and Lemma~\ref{lem:crit} gives $c'$.
\end{proof}

When $N$ is not a perfect square, exactly $\varphi(4N)/2$ of the classes coprime to $4N$ are split. For $N=15$ the split classes modulo $60$ are $\{1,7,11,17,43,49,53,59\}$ and the inert classes are $\{13,19,23,29,31,37,41,47\}$.

\section{Numerical illustration}

\subsection{A pure large-prime relation}
Let $N=15\,916\,539\,906\,629$ and $c=3\,989\,570$ (with $\lfloor\sqrt N\rfloor=3\,989\,553$). Then $f(c)=128\,878\,271$, which is prime: a partial relation with smooth part $1$. We have $N\equiv c^2\equiv 73\,438\,129\pmod{128\,878\,271}$ and $\leg{N}{128\,878\,271}=+1$.

\subsection{A scan}
For the same $N$ and $c=3\,989\,554,\dots,3\,989\,953$, complete factorisation of the $400$ values yields $996$ odd prime divisors, counted across values. All are split, none is inert or ramified, and the largest is about $3.16\times10^9$.

\subsection{Hit counts}
For $N=87\,463$ and every odd prime $r<60$, direct counting agrees with $1+\leg{N}{r}$. The inert primes $5,7,11,23,31,37,47$ have zero hits, and the split primes $3,13,17,19,29,41,43,53,59$ have two.

\subsection{A toy factorisation with large primes}
Take $N=1\,000\,000\,016\,000\,000\,063$, $B=4000$, $L=400\,000$, and sieve the $120\,000$ values with $|c-\sqrt N|\le 60\,000$.
\begin{center}
\begin{tabular}{ll}
\hline
quantity & value\\
\hline
$Q(B)$ (factor base) & $276$\\
$Q(L)$ & $16\,961$\\
full relations & $326$\\
partial relations & $3\,288$\\
distinct large primes & $2\,757$, none inert\\
combined relations from pairing & $531$\\
final matrix & $857$ rows $\times$ $277$ columns\\
\hline
\end{tabular}
\end{center}
The $277$ columns are $Q(B)=276$ primes plus a sign column. A three-row dependency gives $N=1\,000\,000\,007\times1\,000\,000\,009$.

\section{Algorithms}

\begin{algorithm}[Split-set factor base]
Sieve the primes up to $B$. Keep $2$ and each odd $p$ with $N^{(p-1)/2}\not\equiv-1\pmod p$. For kept odd $p\nmid N$, compute the roots $\pm t_p$ of $t^2\equiv N$ by Tonelli--Shanks. Cost: $O(B\log\log B)+O(\pi(B)\log^2B)$. Each kept odd prime has $1+\leg{N}{p}$ sieve progressions.
\end{algorithm}

\begin{algorithm}[Single-large-prime sieve with pairing]
For each $c$, divide $f(c)$ by the factor base to obtain a cofactor $u$. If $u=1$, record a full relation. If $B<u\le L$ and $u$ is prime, store the partial relation in a hash table keyed by $u$; when $L<B^2$, any such cofactor is automatically prime. For each key with relations $\rho_1,\dots,\rho_k$, emit $\rho_1\rho_j$ for $2\le j\le k$. The keys are split primes, so the table can be sized by $Q(L)-Q(B)$.
\end{algorithm}

\begin{algorithm}[$\F_2$ dependency]
Encode relations as bit vectors of length $Q(B)+1$. Perform incremental Gaussian elimination, tracking for each pivot the mask of rows combined into it. A row reducing to zero yields a dependency, which happens after at most $Q(B)+2$ rows. Cost: $O(R\,Q(B)^2/w)$ word operations.
\end{algorithm}

\section{Discussion}
The large primes were hoped to supply columns outside the split set. Theorem~\ref{thm:split} shows they lie inside it by construction. Theorem~\ref{thm:periodic} shows the constraint cannot be bypassed by selection. Theorem~\ref{thm:combined} shows that the large primes vanish from the final linear algebra. The large-prime variant remains an effective accelerator: in the toy run it raised the number of final rows from $326$ to $857$ on the same sieve interval. Theorem~\ref{thm:forms} shows that multiple polynomials do not produce non-split primes either. Whether multiple polynomials or an adaptive $B$ can change the cost trade-off in other ways remains open.

\section{Conjectures and future directions}

\begin{conjecture}[Split-restricted birthday law]
Among $m$ partial relations with large primes in $(B,L]$, the expected number of repeated large primes is approximately $m^2/\bigl(2(Q(L)-Q(B))\bigr)$ for $m\ll\sqrt{Q(L)-Q(B)}$. This is about twice the naive all-primes rate.
\end{conjecture}
In a uniform-draw simulation with $m=60$, $B=2000$, $L=200\,000$ and the $N$ of \S7.1 ($Q(L)-Q(B)=8721$, $\pi(L)-\pi(B)=17\,681$), the prediction $0.206$ compares with a simulated $0.216$, while the naive model gives $0.102$.

\begin{conjecture}[Adaptive-$B$ column monotonicity]
For any schedule $B_1\le\dots\le B_{\max}$, the final column count is $Q(B_{\max})$, and the work needed for $Q(B_{\max})+1$ rows cannot fall below the static optimum.
\end{conjecture}

\begin{conjecture}[Equidistribution in split classes]
Large primes of partial relations are asymptotically equidistributed over the $\varphi(4N)/2$ split classes modulo $4N$.
\end{conjecture}

\begin{conjecture}[Double-large-prime cycle rank]
In the graph on split primes, with one edge per relation carrying two large primes, the number of independent combined relations equals $\#\text{edges}-\#\text{vertices}+\#\text{components}$. Each such relation is supported on the $Q(B)$ small columns.
\end{conjecture}

\section{Conclusion}
A prime that divides $c^2-N$ sees $N$ as a square. The large primes of the partial-relation variant are therefore split primes. Their splitness is fixed by their class modulo $4N$, and after pairing they cancel, leaving $Q(B)$ columns. The large-prime variant increases the yield of rows. It does not change the column side of the trade-off.

