from __future__ import annotations

import math
from typing import Dict, List, Tuple


def primes_upto(n: int) -> List[int]:
    """Sieve of Eratosthenes."""
    if n < 2:
        return []
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for i in range(2, math.isqrt(n) + 1):
        if s[i]:
            s[i * i :: i] = bytearray(len(range(i * i, n + 1, i)))
    return [i for i in range(n + 1) if s[i]]


def legendre(a: int, p: int) -> int:
    """Legendre symbol (a/p) for an odd prime p via Euler's criterion."""
    a %= p
    if a == 0:
        return 0
    return 1 if pow(a, (p - 1) // 2, p) == 1 else -1


def tonelli_shanks(n: int, p: int) -> int:
    """A square root of the nonzero square n modulo the odd prime p."""
    n %= p
    if p % 4 == 3:
        return pow(n, (p + 1) // 4, p)
    q, s = p - 1, 0
    while q % 2 == 0:
        q //= 2
        s += 1
    z = 2
    while legendre(z, p) != -1:
        z += 1
    m, c, t, r = s, pow(z, q, p), pow(n, q, p), pow(n, (q + 1) // 2, p)
    while t != 1:
        i, t2 = 0, t
        while t2 != 1:
            t2 = t2 * t2 % p
            i += 1
        b = pow(c, 1 << (m - i - 1), p)
        m, c, t, r = i, b * b % p, t * b * b % p, r * b % p
    return r


def split_factor_base(N: int, B: int) -> List[Tuple[int, List[int]]]:
    """Primes p <= B at which N is a square, with the residues c mod p hit by p.

    The number of residues for an odd prime p is exactly 1 + (N/p)."""
    out: List[Tuple[int, List[int]]] = []
    for p in primes_upto(B):
        if p == 2:
            out.append((2, [N % 2]))
            continue
        s = legendre(N, p)
        if s == -1:
            continue  # inert: never divides c^2 - N
        if s == 0:
            out.append((p, [0]))
            continue
        t = tonelli_shanks(N, p)
        out.append((p, sorted({t, p - t})))
        assert len(out[-1][1]) == 1 + s
    return out


if __name__ == "__main__":
    fb = split_factor_base(87463, 60)
    print("Q(B) =", len(fb))
    for p, roots in fb:
        print(p, roots)

from __future__ import annotations

import math
from collections import defaultdict
from typing import Dict, List, Tuple


def primes_upto(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for i in range(2, math.isqrt(n) + 1):
        if s[i]:
            s[i * i :: i] = bytearray(len(range(i * i, n + 1, i)))
    return [i for i in range(n + 1) if s[i]]


def legendre(a: int, p: int) -> int:
    a %= p
    if a == 0:
        return 0
    return 1 if pow(a, (p - 1) // 2, p) == 1 else -1


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


Relation = Tuple[int, Dict[int, int], int]  # (X, exponents incl. sign col -1, cofactor product)


def lp_sieve_with_pairing(N: int, B: int, L: int, span: int
                          ) -> Tuple[List[int], List[Relation], int]:
    """Single-large-prime sieve.  Returns (factor base, final relations, #inert large primes).

    Each final relation (X, e, R) satisfies X^2 = sign * prod p^e_p * R^2 (mod N), where R is
    the product of the cancelled large primes.  Its odd-exponent support lies in the factor
    base, so the final matrix has Q(B) + 1 columns regardless of L."""
    base = [p for p in primes_upto(B) if p == 2 or legendre(N, p) == 1]
    c0 = math.isqrt(N) + 1
    fulls: List[Relation] = []
    partials: Dict[int, List[Tuple[int, Dict[int, int]]]] = defaultdict(list)
    inert = 0
    for x in range(c0 - span, c0 + span):
        v = x * x - N
        if v == 0:
            continue
        u, e = abs(v), {}
        if v < 0:
            e[-1] = 1
        for p in base:
            k = 0
            while u % p == 0:
                u //= p
                k += 1
            if k:
                e[p] = k
        if u == 1:
            fulls.append((x, e, 1))
        elif B < u <= L and is_prime(u):
            if legendre(N, u) == -1:
                inert += 1  # the theorem says this never happens
            partials[u].append((x, e))
    combined: List[Relation] = []
    for r, group in partials.items():
        x1, e1 = group[0]
        for x2, e2 in group[1:]:
            e = dict(e1)
            for p, k in e2.items():
                e[p] = e.get(p, 0) + k
            combined.append((x1 * x2 % N, e, r))  # r^2 cancels mod 2
    return base, fulls + combined, inert


if __name__ == "__main__":
    base, rels, inert = lp_sieve_with_pairing(1000036000099, 400, 16000, 15000)
    print(f"Q(B) = {len(base)}, final rows = {len(rels)}, inert large primes = {inert}")

from __future__ import annotations

import math
from typing import Dict, List, Optional, Tuple


def gf2_dependency(rows: List[Dict[int, int]], cols: List[int]) -> Optional[List[int]]:
    """Incremental Gaussian elimination over GF(2) with combination tracking.

    rows[k] maps column labels to exponents; only parities matter.  Returns the indices of
    a nonempty set of rows whose exponent vectors sum to zero mod 2, or None.  With
    len(cols) columns a dependency is guaranteed once len(rows) > len(cols)."""
    index = {c: i for i, c in enumerate(cols)}
    pivots: Dict[int, Tuple[int, int]] = {}
    for k, row in enumerate(rows):
        vec = 0
        for c, e in row.items():
            if e % 2:
                vec ^= 1 << index[c]
        comb = 1 << k
        while vec:
            top = vec.bit_length() - 1
            if top not in pivots:
                pivots[top] = (vec, comb)
                break
            pv, pc = pivots[top]
            vec ^= pv
            comb ^= pc
        if vec == 0:
            return [i for i in range(len(rows)) if comb >> i & 1]
    return None


def square_root_step(N: int, chosen: List[Tuple[int, Dict[int, int], int]]) -> int:
    """Given relations X_i^2 = prod p^e * R_i^2 whose exponents sum to even, return gcd(X - Y, N)."""
    X, Y, tot = 1, 1, {}
    for x, e, r in chosen:
        X = X * x % N
        Y = Y * r % N
        for p, k in e.items():
            tot[p] = tot.get(p, 0) + k
    for p, k in tot.items():
        if p > 0:
            Y = Y * pow(p, k // 2, N) % N
    return math.gcd(X - Y, N)


